using System;using System.Linq;using System.Reflection;using System.IO;using Verse;using UnityEngine;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){var d=(Dialog_MiniGame)Host.State["idleDialog"];var f=BindingFlags.Instance|BindingFlags.NonPublic;var pair=(Pawn[])Host.State["idleParticipants"];var log=Host.Root+"/idle-after-hover-r2.txt";File.WriteAllText(log,"After pointer leaves actual result window.\n");int start=Find.TickManager.TicksGame,stage=0;float real=Time.realtimeSinceStartup;Host.Watch=()=>{int e=Find.TickManager.TicksGame-start;bool released=(bool)typeof(Dialog_MiniGame).GetField("released",f).GetValue(d);if(stage==0&&released&&e>150){File.AppendAllText(log,"released="+released+" windowRetained="+Find.WindowStack.Windows.Contains(d)+" jobs="+pair[0].CurJobDef+","+pair[1].CurJobDef+" real="+(Time.realtimeSinceStartup-real)+"\n");typeof(Dialog_MiniGame).GetMethod("StartAnotherMatch",f).Invoke(d,null);stage=1;start=Find.TickManager.TicksGame;}else if(stage==1){var now=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(now!=null||e>1800){File.AppendAllText(log,"after release practice New game opened="+(now!=null)+" sameOpponent="+(now!=null&&typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(now)==pair[1])+"\n");Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;}}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Observe post-hover release and rematch after participants return to ordinary jobs.";}}
